-- 0092: Ek kurumsal sayfalar (kariyer + SSS) ve kısa adres yönlendirmeleri.

INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'İnsan Kaynakları ve Kariyer', 'insan-kaynaklari', 'theblock.com.tr''de açık pozisyonlar, başvuru süreci ve staj imkânları.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "theblock.com.tr, dijital haber yayıncılığında deneyim kazanmak isteyen gazeteciler, editörler, tasarımcılar ve yazılım geliştiriciler için ekip büyütmeyi sürdürüyor. Bağımsız haberciliğe inanan, merak eden ve üreten insanlarla çalışıyoruz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Çalışma Kültürümüz"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hızlı ama doğrulanmış habercilik: hız, doğruluğun önüne geçmez."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Şeffaf iletişim ve geri bildirim kültürü."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Uzaktan ve hibrit çalışma imkânı (role göre)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Mesleki gelişim için eğitim ve kaynak desteği."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Editoryal bağımsızlık: reklam ve haber ekipleri ayrıdır."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Açık Pozisyonlar"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Açık pozisyonlar dönemsel olarak değişir. Genel olarak aşağıdaki alanlarda başvuru kabul ediyoruz:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Muhabir / editör (ekonomi, siyaset, dünya, spor, teknoloji)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Görsel yönetmen, fotoğraf editörü, video kurgu."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Frontend / backend geliştirici, veri analisti."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sosyal medya ve bülten editörü."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Grafik tasarımcı ve infografik üretici."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Başvuru Süreci"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Özgeçmişinizi ve (varsa) portfolyonuzu kariyer@theblock.com.tr adresine gönderin."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Uygun bulunan başvurular için kısa bir ön görüşme planlanır."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Role göre editöryal veya teknik bir değerlendirme yapılır."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Son görüşme ve referans kontrolünün ardından teklif iletilir."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Başvurunuzda hangi alanda çalışmak istediğinizi, deneyiminizi ve örnek çalışmalarınızı belirtmeniz süreci hızlandırır. Kişisel verileriniz yalnızca işe alım amacıyla işlenir; ayrıntılar KVKK Aydınlatma Metni''nde yer alır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Staj ve Yeni Mezun"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Haber merkezi ve teknoloji ekibinde dönemsel staj programları yürütülür. Staj başvurularında öğrenim durumunuzu, ilgi alanlarınızı ve varsa yayımlanmış çalışmalarınızı belirtin. Staj süresi ve koşulları başvuru değerlendirmesinde paylaşılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Eşit Fırsat"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Başvurularda cinsiyet, yaş, etnik köken, inanç, engellilik veya medeni durum ayrımı yapılmaz. Yalnızca işin gerektirdiği yetkinlikler değerlendirilir. Erişilebilirlik ihtiyaçlarınız için bize önceden bilgi verebilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. İletişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kariyer ve staj sorularınız için kariyer@theblock.com.tr adresine yazabilirsiniz. Başvurular, değerlendirme süreci sonunda mevzuatta öngörülen süre boyunca saklanır."}]}]}'::jsonb, 'yayinda', false, true, true)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, spot = EXCLUDED.spot,
    detail = EXCLUDED.detail, status = 'yayinda', in_footer = true, updated_at = now();

INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Sıkça Sorulan Sorular', 'sikca-sorulan-sorular', 'Üyelik, yorum, bülten, reklam ve içerik kullanımına ilişkin sık sorulan sorular.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Okuyucularımızdan en sık gelen soruları ve yanıtlarını bu sayfada topladık. Aradığınız yanıtı bulamazsanız İletişim sayfasındaki kanallardan bize ulaşabilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Üyelik ve Hesap"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Üyelik ücretli mi?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitedeki haberleri okumak ücretsizdir. Üyelik; yorum yapma, içerik kaydetme ve tercihlerin hatırlanması gibi ek işlevler için kullanılır. Ücretli abonelik gerektiren özel içerikler ayrıca etiketlenir."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Şifremi unuttum, ne yapmalıyım?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Giriş ekranındaki \"Şifremi unuttum\" bağlantısını kullanarak e-posta adresinize sıfırlama bağlantısı gönderebilirsiniz. Bağlantı gelmezse spam klasörünü kontrol edin ve gerekirse info@theblock.com.tr adresine yazın."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Hesabımı nasıl silerim?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Hesabınızın ve kişisel verilerinizin silinmesi için İlgili Kişi Başvuru Formu sayfasındaki yöntemi kullanabilirsiniz. Talebiniz mevzuattaki süre içinde değerlendirilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Yorumlar"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Yorumum neden yayınlanmadı?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Yorumlar; hakaret, nefret söylemi, spam, reklam veya kişisel veri içermesi hâlinde yayınlanmaz. Ayrıca çok kısa veya konuyla ilgisiz yorumlar moderasyonda elenebilir."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Yorumumu düzeltebilir miyim?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Yayınlanmış yorumların düzenlenmesi mümkün değildir; kaldırılması için info@theblock.com.tr adresine bağlantı ile birlikte yazabilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Bülten"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bültene nasıl abone olurum?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitedeki bülten alanından e-posta adresinizle abone olabilirsiniz. Aboneliğinizi her bültendeki bağlantıdan tek tıkla sonlandırabilirsiniz."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bülten gelmiyor?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Spam/gereksiz klasörünüzü kontrol edin ve gönderici adresini güvenli listeye ekleyin. Sorun sürerse destek@theblock.com.tr adresine yazın."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "İçerik ve Telif"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Haberlerinizi kullanabilir miyim?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kaynak ve bağlantı göstererek kısa alıntı yapabilirsiniz. İçeriklerin bütün olarak veya ticari amaçla kullanımı için yazılı izin gerekir. Ayrıntılar için Telif Hakları sayfasına bakın."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bir haberde hata var, nasıl bildiririm?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "duzeltme@theblock.com.tr adresine içeriğin bağlantısını ve düzeltilmesi gereken noktayı yazın. Doğrulama sonrası gerekli düzeltme yapılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Reklam ve İş Birliği"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Reklam vermek istiyorum, kime yazmalıyım?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "reklam@theblock.com.tr adresine yazabilirsiniz. Medya kiti, yerleşim seçenekleri ve fiyat bilgisi talep üzerine paylaşılır."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Sponsorlu içerikler nasıl etiketleniyor?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ticari iş birlikleri \"Sponsorlu\" veya \"İş birliği\" etiketiyle gösterilir. Ayrıntılar için Reklam ve Sponsorluk Politikası sayfasına bakın."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Teknik"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Site mobilde yavaş açılıyor"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tarayıcı önbelleğini temizlemeyi ve güncel tarayıcı sürümü kullanmayı deneyin. Sorun devam ederse cihaz ve tarayıcı bilgisiyle destek@theblock.com.tr adresine yazın."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Karanlık tema nasıl açılır?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Üst menüdeki tema düğmesiyle açık/karanlık tema arasında geçiş yapabilirsiniz. Tercihiniz tarayıcınızda saklanır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Hâlâ sorunuz mu var?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "İletişim sayfamızdaki e-posta adreslerinden bize ulaşabilirsiniz. Haber merkezi 7/24 çalışır; diğer talepler hafta içi mesai saatlerinde yanıtlanır."}]}]}'::jsonb, 'yayinda', false, true, true)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, spot = EXCLUDED.spot,
    detail = EXCLUDED.detail, status = 'yayinda', in_footer = true, updated_at = now();

INSERT INTO redirects (site_id, source_path, target_url, status_code)
SELECT s.id, r.src, r.dst, 301 FROM sites s CROSS JOIN (VALUES
    ('/hakkimizda', '/kunye'),
    ('/about', '/kunye'),
    ('/kariyer', '/insan-kaynaklari'),
    ('/sss', '/sikca-sorulan-sorular')
) AS r(src, dst)
ON CONFLICT (site_id, source_path) DO UPDATE SET target_url = EXCLUDED.target_url, status_code = 301;

-- Footer Kurumsal sütununa Kariyer ve SSS bağlantılarını ekle.
UPDATE settings SET value = jsonb_set(value, '{cols}', (
    SELECT jsonb_agg(CASE WHEN c->>'title' = 'Kurumsal'
        THEN jsonb_set(c, '{links}', '[{"label": "Çerez Politikası", "url": "/cerez-politikasi"}, {"label": "Kullanım Koşulları", "url": "/kullanim-kosullari"}, {"label": "Gizlilik Politikası", "url": "/gizlilik-politikasi"}, {"label": "KVKK Aydınlatma", "url": "/kvkk"}, {"label": "İlgili Kişi Başvuru Formu", "url": "/kvkk-basvuru"}, {"label": "Telif Hakları", "url": "/telif-haklari"}, {"label": "Editoryal İlkeler", "url": "/editoryal-ilkeler"}, {"label": "Bilgi Toplum Hizmetleri", "url": "/bilgi-toplum-hizmetleri"}, {"label": "Künyemiz", "url": "/kunye"}, {"label": "Bize Ulaşın", "url": "/iletisim"}, {"label": "Kariyer", "url": "/insan-kaynaklari"}, {"label": "Sıkça Sorulan Sorular", "url": "/sikca-sorulan-sorular"}]'::jsonb) ELSE c END ORDER BY ord)
    FROM jsonb_array_elements(value->'cols') WITH ORDINALITY AS t(c, ord)
)) WHERE section = 'footer' AND key = 'ana' AND value ? 'cols';

